// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createHighlight,
    deleteHighlight,
    deleteLink,
    deleteCollection
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const collectionsPostResponse = await createCollection(client, "Testbot Delete 404", "#0ea5e9");
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe("Testbot Delete 404");

    const linksPostResponse = await createLink(
        client,
        "Testbot Delete 404 Source",
        "https://example.com/testbot-delete-404",
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.url"), 'link url').toBe("https://example.com/testbot-delete-404");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'link collection').toBe(getResponseValue(collectionsPostResponse, "response.id"));

    const highlightsPostResponse = await createHighlight(
        client,
        getResponseValue(linksPostResponse, "response.id"),
        "red",
        "Testbot delete-404 passage",
        "to be deleted",
        0,
        26
    );
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'highlight colour').toBe("red");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'highlight text').toBe("Testbot delete-404 passage");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'highlight note').toBe("to be deleted");
    expect(getResponseValue(highlightsPostResponse, "response.id"), 'highlight id').toBeGreaterThan(0);

    const highlightsHighlightsDeleteResponse = await deleteHighlight(
        client,
        getResponseValue(highlightsPostResponse, "response.id")
    );
    expect(highlightsHighlightsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsHighlightsDeleteResponse, "response"), 'a successful delete returns the deleted id').toBe(getResponseValue(highlightsPostResponse, "response.id"));

    const highlightsHighlightsDelete1Response = await deleteHighlight(
        client,
        getResponseValue(highlightsPostResponse, "response.id"),
        404
    );
    expect(highlightsHighlightsDelete1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(highlightsHighlightsDelete1Response, "response"), 'deleting an already-deleted highlight fails cleanly').toBe("Highlight not found.");

    const highlights999999999DeleteResponse = await deleteHighlight(client, 999999999, 404);
    expect(highlights999999999DeleteResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(highlights999999999DeleteResponse, "response"), 'deleting an id that never existed fails cleanly').toBe("Highlight not found.");

    const linksLinksDeleteResponse = await deleteLink(client, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted the link this test created').toBe(getResponseValue(linksPostResponse, "response.id"));

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, getResponseValue(collectionsPostResponse, "response.id"));
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted the collection this test created').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
